import { writeFileSync, readFileSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { nativeWorkbench } from '../../apps/chataigne/ui/tests/browser/native-workbench.mjs';
import { expand, pad } from '../../apps/chataigne/ui/tests/browser/app-graph-scale/projects.mjs';
import { spatializerScaleContract as contract } from '../../apps/chataigne/ui/tests/browser/app-graph-scale/spatializer-contract.mjs';

// One operation for caller attribution only; never a qualification distribution.
await nativeWorkbench({
  fixture: new URL('../../apps/chataigne/ui/tests/browser/spatializer-fixture/', import.meta.url),
  name: 'p11-spatializer-creation-phases',
  async exercise({ page, evidence, emit }) {
    const call = (method, ...args) => page.evaluate(
      ({ method, args }) => window.spatializerFixture[method](...args), { method, args }
    );
    await page.waitForFunction(() => window.spatializerFixture?.status().connection === 'connected');
    const { project, metadata } = expand('spatializer', 2849, { mode: 'voronoi', sources: 32 });
    pad(project, 4);
    const path = resolve(evidence, 'scene.noisette');
    writeFileSync(path, JSON.stringify(project));
    await call('load', path);
    await page.waitForFunction(() => {
      const s = window.spatializerFixture.scaleScene();
      return s.treeNodes === 100000 && s.cells === 91168 && s.pending === 0;
    }, null, { timeout: 300000, polling: 500 });
    await call('scaleReady', 10000);
    const endpoints = await call('endpoints'), byUuid = new Map(endpoints.map(e => [e.uuid, e]));
    const sources = metadata.sourceItems.map(uuid => byUuid.get(uuid).id);
    const targets = metadata.items.map(uuid => byUuid.get(uuid).id);
    const scene = await call('scaleScene'), owner = await call('readNode', scene.module);
    const children = await Promise.all(owner.children.map(id => call('readNode', id)));
    const values = children.find(n => n.decl_id === 'values' || n.decl_id.endsWith('/values')).node_id;
    const before = await call('status');
    emit({ kind: 'attribution-start', diagnosticOnly: true, before });
    const cdp = await page.context().newCDPSession(page);
    await cdp.send('Profiler.enable');
    await cdp.send('Profiler.start');
    const phases = [];
    const progress = (message) => {
      const prefix = 'spatializer-measurement:';
      if (!message.text().startsWith(prefix)) return;
      const value = JSON.parse(message.text().slice(prefix.length));
      if (value.caseId === 'single-creation-attribution')
        phases.push({ ...value, backendBytes: statSync(resolve(evidence, 'headless.log')).size });
    };
    page.on('console', progress);
    const timing = await call('measureScale', 'create', {
      caseId: 'single-creation-attribution', mode: 'voronoi', sources, targets, values,
      treeNodes: 100000, warmups: 0, retained: 1, gates: contract.stress, limits: contract.limits
    });
    page.off('console', progress);
    const backend = readFileSync(resolve(evidence, 'headless.log'));
    const ranges = [['creation', 'prepare', 'sample'], ['undo', 'restore', 'restored']].map(([name, from, to]) => {
      const start = phases.find(p => p.phase === from).backendBytes;
      const end = phases.find(p => p.phase === to).backendBytes;
      const snapshots = backend.subarray(start, end).toString('utf8').split(/\r?\n/).filter(line => line.startsWith('[engine] process_snapshot')).map(line => {
        const refresh = line.match(/process_snapshot_refresh nodes=(\d+) captured=(\d+) compacted=(\d+) total_us=(\d+) caller=(.*)$/);
        if (refresh) return { kind: 'refresh', nodes: +refresh[1], captured: +refresh[2], compacted: +refresh[3], totalUs: +refresh[4], caller: refresh[5] };
        const m = line.match(/nodes=(\d+) clone_us=(\d+) count_us=(\d+) indexes_us=(\d+) caller=(.*)$/);
        return m && { nodes: +m[1], totalUs: +m[2] + +m[3] + +m[4], caller: m[5] };
      }).filter(Boolean);
      return { name, start, end, snapshots };
    });
    emit({ kind: 'creation-phases', diagnosticOnly: true, phases, ranges });
    const { profile } = await cdp.send('Profiler.stop');
    writeFileSync(resolve(evidence, 'single.cpuprofile'), JSON.stringify(profile));
    const counts = new Map();
    for (let i = 0; i < (profile.samples?.length ?? 0); i++)
      counts.set(profile.samples[i], (counts.get(profile.samples[i]) ?? 0) + (profile.timeDeltas?.[i] ?? 0));
    const cpu = profile.nodes.map(n => ({ id: n.id, frame: n.callFrame, selfUs: counts.get(n.id) ?? 0 }))
      .sort((a, b) => b.selfUs - a.selfUs).slice(0, 40);
    emit({ kind: 'creation-attribution', diagnosticOnly: true, timing, before, after: await call('status'), cpu });
  }
});
